INSERT INTO public.lessons (id, skill_id, title, summary_md, key_points, resource_ids, estimated_minutes, is_core, status, ai_drafted, version) VALUES
($s$lesson-programming-fundamentals$s$, $s$programming-fundamentals$s$, $s$Programming Fundamentals$s$, $s$Every language shares the same building blocks: **values and variables**, **conditionals and loops**, and **functions** that turn inputs into outputs. Learn to read an error message, add a print/log statement, and step through code in a debugger before moving on.$s$, ARRAY[$s$Variables hold values; types decide what operations are valid$s$,$s$Loops and conditionals control which code runs$s$,$s$Functions take inputs and return outputs; keep them small$s$,$s$Debug by reproducing, isolating and checking one assumption at a time$s$]::text[], ARRAY[$s$learncpp$s$,$s$cppreference$s$,$s$dev-java$s$,$s$python-collections$s$,$s$clean-code-book$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-cli-basics$s$, $s$cli-basics$s$, $s$Command Line Basics$s$, $s$The terminal is where developer tools live. Learn to move around (`cd`, `ls`, `pwd`), inspect files (`cat`, `less`, `grep`), and combine commands with pipes (`|`) and redirection (`>`). Environment variables and `PATH` explain why a command is or is not found.$s$, ARRAY[$s$Paths can be absolute or relative to the working directory$s$,$s$Pipes send one command's output into another$s$,$s$Environment variables configure programs; PATH lists where executables are searched$s$,$s$Exit code 0 means success$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-git$s$, $s$git$s$, $s$Git & Version Control$s$, $s$Git records snapshots of your project as **commits**. Work happens on **branches**, which are merged back after review in a **pull request**. Know the everyday loop (`status`, `add`, `commit`, `pull`, `push`), how to resolve a merge conflict, and why you never rewrite shared history.$s$, ARRAY[$s$A commit is a snapshot plus a message explaining why$s$,$s$Branches isolate work; merges or rebases bring it back$s$,$s$Merge conflicts are resolved by editing the file and committing$s$,$s$Pull requests are where code review happens$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-http-fundamentals$s$, $s$http-fundamentals$s$, $s$How the Web Works (HTTP)$s$, $s$A browser sends an **HTTP request** (method, URL, headers, optional body) and a server returns a **response** (status code, headers, body). GET reads, POST creates, PUT/PATCH update, DELETE removes. Status classes tell you what happened: 2xx success, 3xx redirect, 4xx client error, 5xx server error.$s$, ARRAY[$s$HTTP is stateless; cookies and tokens carry identity between requests$s$,$s$Methods describe intent; GET must not change data$s$,$s$4xx means the client sent something wrong, 5xx means the server failed$s$,$s$HTTPS adds TLS encryption on top of HTTP$s$]::text[], ARRAY[$s$mdn-http-overview$s$]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-dsa$s$, $s$dsa$s$, $s$Data Structures & Algorithms$s$, $s$Most interview problems reduce to a handful of patterns: **hash maps** for lookups, **two pointers / sliding window** on arrays, **BFS/DFS** on trees and graphs, **heaps** for top-k, and **dynamic programming** for overlapping subproblems. Always state the time and space complexity in Big-O.$s$, ARRAY[$s$Hash maps give O(1) average lookups$s$,$s$Sorting is O(n log n); many problems get easier after sorting$s$,$s$BFS finds shortest paths in unweighted graphs$s$,$s$Dynamic programming caches answers to repeated subproblems$s$]::text[], ARRAY[$s$mit-6006$s$,$s$visualgo$s$,$s$cses-book$s$,$s$cp-algorithms$s$,$s$cppreference$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-testing-fundamentals$s$, $s$testing-fundamentals$s$, $s$Software Testing$s$, $s$Tests let you change code without fear. **Unit tests** check one function in isolation, **integration tests** check pieces working together, and **end-to-end tests** drive the real app. Follow Arrange-Act-Assert, keep tests deterministic, and mock only what you do not own.$s$, ARRAY[$s$The testing pyramid: many unit tests, fewer integration, few end-to-end$s$,$s$Arrange, Act, Assert$s$,$s$Flaky tests usually depend on time, order or the network$s$,$s$TDD: write a failing test, make it pass, refactor$s$]::text[], ARRAY[$s$clean-code-book$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-system-design$s$, $s$system-design$s$, $s$System Design$s$, $s$System design interviews test structured trade-off thinking. Clarify requirements and scale, sketch the **API and data model**, then add **load balancers, caches, replicas, shards and queues** only where the numbers demand them. Name the trade-offs explicitly: consistency vs availability, latency vs cost.$s$, ARRAY[$s$Start from requirements and back-of-the-envelope numbers$s$,$s$Scale reads with caches and replicas, writes with sharding and queues$s$,$s$CAP: under a partition you choose consistency or availability$s$,$s$Every component you add is a new failure mode$s$]::text[], ARRAY[$s$ddia-book$s$,$s$system-design-primer$s$,$s$bytebytego$s$,$s$ddia-references$s$,$s$yt-distributed-cache-redis$s$]::text[], 45, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-web-security$s$, $s$web-security$s$, $s$Web Security (OWASP)$s$, $s$Most breaches exploit a short list of mistakes. **Injection** (SQL, command) is prevented with parameterised queries; **XSS** with output encoding and a Content Security Policy; **CSRF** with SameSite cookies or tokens. Never trust client input, store passwords with a slow hash, and keep secrets out of the repo.$s$, ARRAY[$s$Parameterised queries stop SQL injection$s$,$s$Escape output and use CSP against XSS$s$,$s$CORS controls which origins may read responses; it is not authentication$s$,$s$Hash passwords with bcrypt/argon2, never plain SHA$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-behavioral-interviews$s$, $s$behavioral-interviews$s$, $s$Behavioral Interviews (STAR)$s$, $s$Behavioral answers follow **STAR**: Situation, Task, Action, Result. Prepare 6-8 stories that cover impact, conflict, failure, ambiguity and leadership, and quantify results. Spend most of the answer on **your** actions, not the team's.$s$, ARRAY[$s$Situation and Task set context in two sentences$s$,$s$Action is the longest part and uses "I"$s$,$s$Results are measurable and include what you learned$s$,$s$Reuse stories across questions by changing emphasis$s$]::text[], ARRAY[$s$cracking-the-pm-interview$s$,$s$tih-resume$s$,$s$tih-behavioral$s$]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-html$s$, $s$html$s$, $s$HTML5 & Semantic Markup$s$, $s$HTML describes **what content is**, not how it looks. Use semantic elements (`header`, `nav`, `main`, `article`, `button`) so browsers, search engines and screen readers understand the page. Forms need labels tied to inputs, and every image needs meaningful `alt` text.$s$, ARRAY[$s$Choose elements by meaning: a clickable action is a button$s$,$s$Every form input needs a label$s$,$s$Headings form an outline; do not skip levels$s$,$s$Meta tags control title, description and viewport$s$]::text[], ARRAY[$s$mdn-learn-html$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-css$s$, $s$css$s$, $s$CSS Fundamentals$s$, $s$CSS applies styles through the **cascade**: when rules conflict, the more **specific** selector wins, and later rules beat earlier ones of equal specificity. Every element is a **box** (content, padding, border, margin). Prefer relative units (`rem`, `%`) and set `box-sizing: border-box`.$s$, ARRAY[$s$Specificity: inline > id > class/attribute > element$s$,$s$The box model: content, padding, border, margin$s$,$s$rem scales with the root font size$s$,$s$Custom properties (variables) make themes easy$s$]::text[], ARRAY[$s$fcc-css-grid-flexbox$s$]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-css-layout$s$, $s$css-layout$s$, $s$Flexbox & Grid Layout$s$, $s$**Flexbox** lays items out along one axis: `justify-content` aligns on the main axis and `align-items` on the cross axis. **Grid** handles rows and columns together with `grid-template-columns` and `gap`. Use Flexbox for components, Grid for page layout.$s$, ARRAY[$s$Flexbox is one-dimensional, Grid is two-dimensional$s$,$s$justify-content = main axis, align-items = cross axis$s$,$s$fr units share leftover space in Grid$s$,$s$gap replaces margin hacks between items$s$]::text[], ARRAY[$s$fcc-css-grid-flexbox$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-responsive-design$s$, $s$responsive-design$s$, $s$Responsive Design$s$, $s$Design **mobile-first**: write base styles for small screens, then add `min-width` media queries as space grows. Use fluid units, flexible images (`max-width: 100%`), and the viewport meta tag. Test at real breakpoints and with zoom.$s$, ARRAY[$s$Start with the smallest screen and enhance upward$s$,$s$min-width media queries pair with mobile-first$s$,$s$clamp() creates fluid type and spacing$s$,$s$Always include the viewport meta tag$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-accessibility$s$, $s$accessibility$s$, $s$Web Accessibility (WCAG)$s$, $s$Accessible products work for everyone. Meet **WCAG AA**: text contrast of at least 4.5:1, every action reachable by **keyboard** with a visible focus ring, and semantic HTML before ARIA. Modals must trap focus and return it when closed.$s$, ARRAY[$s$Native elements beat ARIA roles$s$,$s$Contrast 4.5:1 for body text, 3:1 for large text$s$,$s$Everything clickable must be keyboard operable$s$,$s$Announce dynamic changes with live regions$s$]::text[], ARRAY[$s$mdn-learn-html$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-javascript$s$, $s$javascript$s$, $s$JavaScript Fundamentals$s$, $s$JavaScript runs in every browser and on servers via Node.js. Master `let`/`const` and **block scope**, **closures** (functions remember the scope they were created in), objects and **prototypes**, and array methods (`map`, `filter`, `reduce`). Use `===` to avoid type coercion surprises.$s$, ARRAY[$s$const prevents reassignment, not mutation$s$,$s$A closure keeps access to variables from its outer scope$s$,$s$map/filter/reduce return new arrays$s$,$s$=== compares without type coercion$s$]::text[], ARRAY[$s$javascript-info$s$,$s$you-dont-know-js$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-dom-apis$s$, $s$dom-apis$s$, $s$DOM & Browser APIs$s$, $s$The **DOM** is the live tree of the page. Select nodes with `querySelector`, update them, and listen with `addEventListener`. Events **bubble** from the target up to the document, which enables **event delegation**: one listener on a parent handles many children.$s$, ARRAY[$s$Events capture down, then bubble up$s$,$s$Event delegation uses one parent listener$s$,$s$Batch DOM writes to avoid layout thrashing$s$,$s$localStorage is synchronous and string-only$s$]::text[], ARRAY[$s$javascript-info$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-async-javascript$s$, $s$async-javascript$s$, $s$Async JavaScript & the Event Loop$s$, $s$JavaScript is single-threaded; the **event loop** runs one task at a time. After each task it drains the **microtask queue** (promise callbacks) before the next macrotask (timers, I/O). `async/await` is syntax over promises: wrap awaits in `try/catch`, and use `Promise.all` to run independent work in parallel.$s$, ARRAY[$s$Microtasks (promises) run before the next macrotask (setTimeout)$s$,$s$await pauses only the current async function$s$,$s$Promise.all fails fast; Promise.allSettled waits for all$s$,$s$AbortController cancels fetches$s$]::text[], ARRAY[$s$javascript-info$s$,$s$jsconf-event-loop$s$,$s$you-dont-know-js$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-typescript$s$, $s$typescript$s$, $s$TypeScript$s$, $s$TypeScript adds a **static type checker** to JavaScript. Describe shapes with `interface`/`type`, model alternatives with **union types**, and let **narrowing** (`typeof`, `in`, discriminant fields) refine them. **Generics** keep functions reusable without losing types. Avoid `any`; prefer `unknown` at boundaries.$s$, ARRAY[$s$Types are erased at runtime; validate external data separately$s$,$s$Union + discriminant field = safe narrowing$s$,$s$Generics preserve the relationship between input and output types$s$,$s$unknown forces a check before use; any disables checking$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-react$s$, $s$react$s$, $s$React$s$, $s$React builds UIs from **components**: functions that take **props** and return JSX. **State** (`useState`) triggers a re-render when it changes; **effects** (`useEffect`) sync with things outside React. Lists need stable `key`s, and derived values should be computed, not stored in state.$s$, ARRAY[$s$UI is a function of state$s$,$s$Props flow down; events flow up via callbacks$s$,$s$Keys must be stable and unique among siblings$s$,$s$Effects are for syncing with external systems, not for derived data$s$]::text[], ARRAY[$s$react-dev$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-react-state-management$s$, $s$react-state-management$s$, $s$React State Management$s$, $s$Keep state as **local** as possible and lift it only when siblings need it. Use **context** for rarely-changing global values (theme, user), a **store** (Redux Toolkit, Zustand) for complex client state, and a **server-state cache** (TanStack Query) for data fetched from APIs.$s$, ARRAY[$s$Server state and client state are different problems$s$,$s$Context re-renders every consumer on change$s$,$s$Stores allow selecting slices to limit re-renders$s$,$s$Normalise collections by id$s$]::text[], ARRAY[$s$react-dev$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-nextjs$s$, $s$nextjs$s$, $s$Next.js & Server Rendering$s$, $s$Next.js adds file-based **routing** and multiple rendering strategies to React. **Server Components** render on the server and send no JavaScript; **Client Components** (`"use client"`) handle interactivity. Choose static generation for content that rarely changes and server rendering for per-request data.$s$, ARRAY[$s$Server Components cannot use state or effects$s$,$s$Hydration attaches event handlers to server HTML$s$,$s$Static pages are fastest; revalidate to refresh them$s$,$s$Keep secrets in server-only code$s$]::text[], ARRAY[$s$yt-nextjs-server-components$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-tailwind-css$s$, $s$tailwind-css$s$, $s$Tailwind CSS$s$, $s$Tailwind styles elements with small **utility classes** (`flex`, `p-4`, `text-sm`) mapped to a design-token scale. Responsive and state variants (`md:`, `hover:`) replace media queries and pseudo-classes. Extract repeated patterns into components, not long `@apply` blocks.$s$, ARRAY[$s$Utilities map to a consistent spacing/colour scale$s$,$s$Variants: md:, hover:, focus:, dark:$s$,$s$Configure tokens in the theme rather than hard-coding values$s$,$s$Unused classes are purged at build time$s$]::text[], ARRAY[]::text[], 15, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-build-tools$s$, $s$build-tools$s$, $s$Build Tools & Bundlers$s$, $s$Bundlers like **Vite** and **webpack** turn many modules into optimised files for the browser. They transpile TypeScript/JSX, **tree-shake** unused exports and **split** code into chunks. `package.json` declares dependencies; lockfiles pin exact versions for reproducible installs.$s$, ARRAY[$s$ES modules enable tree-shaking$s$,$s$Dynamic import() creates a separate chunk$s$,$s$Lockfiles make installs reproducible$s$,$s$Dev servers use hot module replacement$s$]::text[], ARRAY[]::text[], 15, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-frontend-testing$s$, $s$frontend-testing$s$, $s$Frontend Testing$s$, $s$Test components the way users use them: query by **role and label**, fire real events, and assert on what is visible. Use **Playwright** or Cypress for a few critical end-to-end flows. Avoid testing implementation details like internal state.$s$, ARRAY[$s$getByRole is the preferred query$s$,$s$Wait for UI with findBy/expect.poll instead of sleeps$s$,$s$Mock the network, not your own components$s$,$s$Keep e2e tests to critical paths$s$]::text[], ARRAY[]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-web-performance$s$, $s$web-performance$s$, $s$Web Performance & Core Web Vitals$s$, $s$Core Web Vitals measure user experience: **LCP** (loading, under 2.5 s), **INP** (responsiveness, under 200 ms) and **CLS** (layout stability, under 0.1). Improve them by shipping less JavaScript, lazy-loading below-the-fold content, sizing images, and breaking up long tasks.$s$, ARRAY[$s$LCP: largest element painted; optimise hero images and fonts$s$,$s$INP: break up long tasks on the main thread$s$,$s$CLS: reserve space for images and ads$s$,$s$Measure field data, not just lab scores$s$]::text[], ARRAY[]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-vue$s$, $s$vue$s$, $s$Vue.js$s$, $s$Vue components combine a template, script and styles. Vue 3 tracks dependencies with **Proxy-based reactivity**: `ref` and `reactive` values update the template automatically. The **Composition API** groups logic by feature; **Pinia** is the official store and **Nuxt** adds SSR.$s$, ARRAY[$s$ref() wraps primitives; access with .value in script$s$,$s$computed() caches derived values$s$,$s$v-for needs a :key$s$,$s$Pinia replaces Vuex$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-angular$s$, $s$angular$s$, $s$Angular$s$, $s$Angular is a batteries-included framework built on TypeScript. It uses **dependency injection** for services, **RxJS observables** for async streams, and now **signals** for fine-grained change detection. Modules are giving way to standalone components.$s$, ARRAY[$s$Services are injected, not imported as singletons$s$,$s$Observables are lazy and can be cancelled$s$,$s$Signals avoid zone.js-wide change detection$s$,$s$Use the async pipe to subscribe in templates$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-nodejs$s$, $s$nodejs$s$, $s$Node.js$s$, $s$Node.js runs JavaScript on the server with **non-blocking I/O**: the event loop hands slow work (disk, network) to libuv and continues serving requests. Never block it with heavy CPU work; use worker threads or a queue. Frameworks like Express/Fastify add routing and **middleware**.$s$, ARRAY[$s$One blocked event loop stalls every request$s$,$s$Middleware runs in order and can end the response$s$,$s$Streams process data without loading it all into memory$s$,$s$Handle errors in async routes or the process may crash$s$]::text[], ARRAY[$s$jsconf-event-loop$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-python$s$, $s$python$s$, $s$Python$s$, $s$Python favours readable code. Know the core collections (**list, dict, set, tuple**), comprehensions, and functions with default and keyword arguments. Use **virtual environments** per project and `pip` to install packages. Beware mutable default arguments.$s$, ARRAY[$s$Lists are mutable, tuples are not$s$,$s$dicts preserve insertion order$s$,$s$Comprehensions build collections concisely$s$,$s$Never use a mutable object as a default argument$s$]::text[], ARRAY[$s$python-collections$s$,$s$python-heapq$s$,$s$python-bisect$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-python-web-frameworks$s$, $s$python-web-frameworks$s$, $s$Python Web Frameworks$s$, $s$**FastAPI** uses type hints and Pydantic models to validate requests and generate OpenAPI docs automatically. **Django** is a full framework with ORM, admin and auth. **Flask** is minimal. Pick FastAPI for async APIs, Django for content-heavy apps with an admin.$s$, ARRAY[$s$Pydantic validates and parses request bodies$s$,$s$Dependency injection in FastAPI shares DB sessions and auth$s$,$s$Django ships ORM, migrations and admin$s$,$s$Run async endpoints only with async drivers$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-rest-api-design$s$, $s$rest-api-design$s$, $s$REST API Design$s$, $s$Good REST APIs model **resources** as nouns (`/users/42/orders`) and use HTTP methods for actions. Return precise status codes, paginate lists, validate every input, and make retries safe with **idempotency** (PUT and DELETE are idempotent; use idempotency keys for POST).$s$, ARRAY[$s$Nouns for resources, methods for verbs$s$,$s$201 Created for new resources, 204 for empty success$s$,$s$Cursor pagination is stable under inserts$s$,$s$Idempotency keys make POST retries safe$s$]::text[], ARRAY[$s$google-api-design-guide$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-authentication$s$, $s$authentication$s$, $s$Authentication & Authorization$s$, $s$**Authentication** answers who you are; **authorization** decides what you may do. Sessions store state server-side behind a cookie; **JWTs** are signed, self-contained tokens that cannot be revoked early without extra work. Use **OAuth 2.0 / OIDC** for "Sign in with..." and enforce permissions on the server, never only in the UI.$s$, ARRAY[$s$AuthN = identity, AuthZ = permissions$s$,$s$JWTs are signed, not encrypted$s$,$s$Short-lived access tokens plus refresh tokens$s$,$s$Check permissions server-side on every request$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-sql$s$, $s$sql$s$, $s$SQL$s$, $s$SQL asks questions of tables. `SELECT` columns `FROM` a table, filter rows with `WHERE`, combine tables with **JOINs**, and summarise with `GROUP BY` plus aggregates (`COUNT`, `SUM`, `AVG`). `HAVING` filters groups after aggregation. NULL is not equal to anything, including NULL.$s$, ARRAY[$s$INNER JOIN keeps matches; LEFT JOIN keeps all left rows$s$,$s$WHERE filters rows, HAVING filters groups$s$,$s$Use IS NULL, never = NULL$s$,$s$Logical order: FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY$s$]::text[], ARRAY[$s$sqlbolt$s$,$s$postgresql-tutorial$s$,$s$postgresql-org$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-advanced-sql$s$, $s$advanced-sql$s$, $s$Advanced SQL$s$, $s$**CTEs** (`WITH ...`) name intermediate results and make long queries readable. **Window functions** (`ROW_NUMBER`, `RANK`, `LAG`, running `SUM`) compute across related rows without collapsing them like `GROUP BY` does. They are the core of analytics interviews.$s$, ARRAY[$s$Window functions keep every row$s$,$s$PARTITION BY restarts the window per group$s$,$s$ROW_NUMBER is unique, RANK leaves gaps, DENSE_RANK does not$s$,$s$LAG/LEAD compare a row with its neighbours$s$]::text[], ARRAY[$s$use-the-index-luke$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-database-design$s$, $s$database-design$s$, $s$Relational Data Modeling$s$, $s$Model entities as tables with a **primary key**, and relationships with **foreign keys** (a join table for many-to-many). **Normalise** to remove duplicated facts, then denormalise deliberately for read performance. Let the database enforce rules with NOT NULL, UNIQUE and CHECK constraints.$s$, ARRAY[$s$One fact in one place (normalisation)$s$,$s$Many-to-many needs a join table$s$,$s$Constraints are cheaper than application checks$s$,$s$Denormalise only with a measured reason$s$]::text[], ARRAY[]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-postgresql$s$, $s$postgresql$s$, $s$PostgreSQL & Relational Databases$s$, $s$An **index** (usually a B-tree) turns a full table scan into a fast lookup, at the cost of slower writes. Read plans with `EXPLAIN ANALYZE`. **Transactions** group changes atomically; isolation levels control which concurrent changes you see. Connection pooling keeps databases healthy under load.$s$, ARRAY[$s$Index columns used in WHERE, JOIN and ORDER BY$s$,$s$ACID: atomic, consistent, isolated, durable$s$,$s$EXPLAIN ANALYZE shows the real plan and timings$s$,$s$Use a pooler (PgBouncer) for many short connections$s$]::text[], ARRAY[$s$ddia-book$s$,$s$postgresql-tutorial$s$,$s$postgresql-org$s$,$s$yt-postgresql-indexing$s$]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-nosql$s$, $s$nosql$s$, $s$NoSQL Databases$s$, $s$NoSQL databases trade joins and flexible queries for scale or schema flexibility. **Document stores** (MongoDB) keep related data together; **key-value stores** (DynamoDB, Redis) are designed around known access patterns. Model data from the queries you need, not from entities.$s$, ARRAY[$s$Design around access patterns$s$,$s$Embed data read together; reference data shared widely$s$,$s$Partition keys decide scalability$s$,$s$Many NoSQL stores are eventually consistent by default$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-orms$s$, $s$orms$s$, $s$ORMs & Migrations$s$, $s$ORMs like **Prisma**, **Drizzle** and **SQLAlchemy** map rows to typed objects and generate SQL. Watch for the **N+1 query** problem (one query per row in a loop) and fix it with joins or eager loading. Schema changes go through versioned **migrations** checked into git.$s$, ARRAY[$s$N+1 queries are the classic ORM performance bug$s$,$s$Migrations are versioned and reviewed like code$s$,$s$Make migrations backwards compatible for zero-downtime deploys$s$,$s$Drop to raw SQL for complex reports$s$]::text[], ARRAY[]::text[], 15, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-caching$s$, $s$caching$s$, $s$Caching & Redis$s$, $s$Caches trade freshness for speed. In **cache-aside**, the app reads the cache, falls back to the database on a miss and stores the result with a **TTL**. Invalidation is the hard part: delete or update keys when data changes. **Redis** also offers counters, sorted sets and locks.$s$, ARRAY[$s$Cache-aside: read cache, on miss read DB and populate$s$,$s$Every cached value needs a TTL or an invalidation path$s$,$s$LRU evicts the least recently used key$s$,$s$Beware the thundering herd when a hot key expires$s$]::text[], ARRAY[$s$leetcode-lru-cache$s$,$s$yt-distributed-cache-redis$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-message-queues$s$, $s$message-queues$s$, $s$Queues & Event Streaming$s$, $s$Queues decouple producers from consumers so slow work happens in the background and spikes are absorbed. **RabbitMQ/SQS** deliver tasks to workers; **Kafka** keeps an ordered, replayable log per partition. Most systems give **at-least-once** delivery, so consumers must be **idempotent**.$s$, ARRAY[$s$At-least-once delivery means duplicates happen$s$,$s$Make consumers idempotent$s$,$s$Kafka orders messages within a partition only$s$,$s$Dead-letter queues capture poison messages$s$]::text[], ARRAY[$s$ddia-book$s$]::text[], 36, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-graphql$s$, $s$graphql$s$, $s$GraphQL$s$, $s$GraphQL exposes a typed **schema**; clients ask for exactly the fields they need in one request. **Resolvers** fetch each field, which can cause N+1 queries; batch them with DataLoader. Mutations change data; subscriptions push updates.$s$, ARRAY[$s$One endpoint, client-shaped responses$s$,$s$Resolvers run per field$s$,$s$DataLoader batches and caches lookups$s$,$s$Limit query depth/complexity to prevent abuse$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-microservices$s$, $s$microservices$s$, $s$Microservices & gRPC$s$, $s$Microservices split a system into independently deployable services around **business capabilities**. They talk over HTTP/**gRPC** or events. The cost is distributed failure: add **timeouts, retries with backoff and circuit breakers**, and trace requests across services. Start with a modular monolith.$s$, ARRAY[$s$Each service owns its data$s$,$s$Timeouts and retries with jitter on every remote call$s$,$s$Circuit breakers stop cascading failures$s$,$s$gRPC uses protobuf contracts and HTTP/2$s$]::text[], ARRAY[]::text[], 36, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-go$s$, $s$go$s$, $s$Go (Golang)$s$, $s$Go is a small, compiled language built for services. **Goroutines** are cheap concurrent functions and **channels** pass data between them. Errors are values you check explicitly. Use `context.Context` to cancel work and prevent goroutine leaks.$s$, ARRAY[$s$Goroutines are cheap; leaks are not$s$,$s$Do not communicate by sharing memory; share memory by communicating$s$,$s$Return errors, do not panic$s$,$s$Pass context for cancellation and deadlines$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-java-spring$s$, $s$java-spring$s$, $s$Java & Spring Boot$s$, $s$Java is a statically typed JVM language used in large enterprises. **Spring Boot** wires applications through **dependency injection** and auto-configuration, exposing REST controllers and talking to databases through JPA/Hibernate. Java 21 **virtual threads** make blocking code scale.$s$, ARRAY[$s$Spring manages beans and injects dependencies$s$,$s$@RestController maps HTTP routes$s$,$s$JPA/Hibernate maps entities to tables$s$,$s$Virtual threads make thread-per-request cheap$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-fullstack-architecture$s$, $s$fullstack-architecture$s$, $s$Full Stack Architecture$s$, $s$A full stack feature crosses the UI, an API and the database. Share **types and validation schemas** between client and server so contracts cannot drift, keep business logic on the server, and use **optimistic updates** for snappy UIs with rollback on failure.$s$, ARRAY[$s$One schema validates on both sides$s$,$s$Business rules live on the server$s$,$s$Optimistic UI needs a rollback path$s$,$s$Paginate and cache at the API boundary$s$]::text[], ARRAY[$s$yt-nextjs-server-components$s$]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-deployment-basics$s$, $s$deployment-basics$s$, $s$Deploying Web Apps$s$, $s$Managed platforms like Vercel, Netlify and Render deploy straight from git: every push builds, and pull requests get **preview environments**. Configure secrets as **environment variables**, never in the repo, and keep production, staging and preview separate.$s$, ARRAY[$s$Builds should be reproducible from a clean checkout$s$,$s$Secrets go in environment variables$s$,$s$Preview deployments per pull request$s$,$s$Roll back by redeploying the previous build$s$]::text[], ARRAY[]::text[], 12, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-linux$s$, $s$linux$s$, $s$Linux Administration$s$, $s$Most servers run Linux. Understand **users, groups and file permissions** (`chmod`, `chown`), manage **processes** (`ps`, `top`, `kill`) and **services** with systemd, read logs with `journalctl`, and install software with the package manager.$s$, ARRAY[$s$Permissions: read/write/execute for user, group, others$s$,$s$systemctl starts, stops and enables services$s$,$s$Everything is a file, including devices and sockets$s$,$s$Check disk, memory and load first when debugging$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-bash-scripting$s$, $s$bash-scripting$s$, $s$Shell Scripting$s$, $s$Shell scripts glue tools together. Start scripts with `set -euo pipefail` so errors stop execution, **quote variables** to handle spaces, and use functions and exit codes. When logic grows beyond a page, switch to Python.$s$, ARRAY[$s$set -euo pipefail fails fast$s$,$s$Always quote "$variables"$s$,$s$$? holds the last exit code$s$,$s$Prefer Python for complex logic$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-networking$s$, $s$networking$s$, $s$Networking Fundamentals$s$, $s$Packets travel by **IP address**; **TCP** adds reliable ordered delivery while **UDP** is fast and connectionless. **DNS** maps names to addresses. In the cloud you design **VPCs** with public and private **subnets** (CIDR ranges), route tables and security groups.$s$, ARRAY[$s$TCP is reliable and ordered; UDP is not$s$,$s$DNS resolves names; TTLs control caching$s$,$s$CIDR /24 = 256 addresses$s$,$s$Private subnets reach the internet via NAT$s$]::text[], ARRAY[$s$cloudflare-learning$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-docker$s$, $s$docker$s$, $s$Docker & Containers$s$, $s$A **container image** packages an app with its dependencies; a **container** is a running instance. Write Dockerfiles with **multi-stage builds** to keep images small, order layers so dependencies cache well, run as a **non-root** user, and use Compose for local multi-service setups.$s$, ARRAY[$s$Images are immutable layers; containers add a writable layer$s$,$s$Copy dependency manifests before source to use the layer cache$s$,$s$Multi-stage builds drop build tools from the final image$s$,$s$Run as non-root and pin base image versions$s$]::text[], ARRAY[$s$yt-docker-kubernetes-pipelines$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-ci-cd$s$, $s$ci-cd$s$, $s$CI/CD Pipelines$s$, $s$**Continuous integration** builds and tests every push; **continuous delivery** keeps main always deployable, and **continuous deployment** ships it automatically. Pipelines should be fast (cache dependencies, run jobs in parallel), reproducible, and keep secrets in the CI secret store.$s$, ARRAY[$s$CI runs on every push and pull request$s$,$s$Cache dependencies to keep pipelines fast$s$,$s$Build once, promote the same artifact through environments$s$,$s$Secrets come from the CI secret store$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-kubernetes$s$, $s$kubernetes$s$, $s$Kubernetes$s$, $s$Kubernetes runs containers across a cluster and continuously reconciles the **desired state** you declare. **Pods** run containers, **Deployments** manage replicas and rolling updates, **Services** give stable networking, and **ConfigMaps/Secrets** inject configuration. Set resource requests/limits and health probes.$s$, ARRAY[$s$Declare desired state; controllers reconcile it$s$,$s$Deployments do rolling updates and rollbacks$s$,$s$Readiness probes gate traffic; liveness probes restart$s$,$s$Requests schedule pods, limits cap them$s$]::text[], ARRAY[$s$kubernetes-io$s$,$s$yt-docker-kubernetes-pipelines$s$]::text[], 45, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-cloud-platforms$s$, $s$cloud-platforms$s$, $s$Cloud Platforms (AWS, GCP, Azure)$s$, $s$Every cloud offers the same building blocks: **compute** (VMs, containers, functions), **storage** (object, block, managed databases), **networking** (VPCs, load balancers) and **identity** (IAM). Follow least privilege, spread across availability zones, and tag resources so you can track cost.$s$, ARRAY[$s$IAM: grant the least privilege needed$s$,$s$Use multiple availability zones for resilience$s$,$s$Object storage (S3) for files, managed DBs for data$s$,$s$Set budgets and alerts to avoid surprise bills$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-terraform$s$, $s$terraform$s$, $s$Infrastructure as Code$s$, $s$Infrastructure as code makes environments reproducible and reviewable. **Terraform** compares your configuration with recorded **state** and shows a **plan** before applying. Store state remotely with locking, split code into modules, and never edit managed resources by hand.$s$, ARRAY[$s$plan before apply, every time$s$,$s$Remote state with locking for teams$s$,$s$Modules make infrastructure reusable$s$,$s$Manual changes cause drift$s$]::text[], ARRAY[]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-observability$s$, $s$observability$s$, $s$Monitoring & Observability$s$, $s$Observability rests on three signals: **metrics** (cheap numbers over time), **logs** (detailed events) and **traces** (a request's path across services). Watch the four golden signals: latency, traffic, errors and saturation. Alert on user-facing symptoms, not every CPU spike.$s$, ARRAY[$s$Metrics, logs, traces$s$,$s$Golden signals: latency, traffic, errors, saturation$s$,$s$Structured logs are searchable$s$,$s$Alert on symptoms that need a human$s$]::text[], ARRAY[]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-sre-practices$s$, $s$sre-practices$s$, $s$SRE & Incident Response$s$, $s$SRE turns reliability into numbers. An **SLI** measures something users feel (e.g. successful requests), an **SLO** sets the target (99.9%), and the **error budget** is the allowed failure that decides between shipping features and fixing reliability. Incidents end with a **blameless postmortem**.$s$, ARRAY[$s$SLI = measurement, SLO = target, SLA = contract$s$,$s$99.9% monthly allows about 43 minutes of downtime$s$,$s$Error budgets balance velocity and reliability$s$,$s$Postmortems fix systems, not people$s$]::text[], ARRAY[]::text[], 30, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-gitops$s$, $s$gitops$s$, $s$GitOps (Argo CD)$s$, $s$In GitOps the desired cluster state lives in a git repository, and an agent like **Argo CD** continuously syncs the cluster to it. Deployments become pull requests, rollbacks become reverts, and drift is detected automatically.$s$, ARRAY[$s$Git is the single source of truth$s$,$s$An in-cluster agent pulls changes$s$,$s$Rollback = git revert$s$,$s$Drift is detected and corrected$s$]::text[], ARRAY[]::text[], 18, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-devsecops$s$, $s$devsecops$s$, $s$DevSecOps & Container Security$s$, $s$DevSecOps builds security into the pipeline: **scan dependencies and images** (e.g. Trivy), run **SAST/DAST**, keep secrets in a manager, sign artifacts, and run containers with least privilege. Fail the build on critical findings.$s$, ARRAY[$s$Scan images and dependencies in CI$s$,$s$Secrets live in a secrets manager, not env files in git$s$,$s$Least privilege for workloads and pipelines$s$,$s$Sign and verify build artifacts$s$]::text[], ARRAY[]::text[], 24, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-nginx$s$, $s$nginx$s$, $s$Web Servers & Reverse Proxies$s$, $s$A **reverse proxy** like Nginx sits in front of app servers: it terminates **TLS**, serves static files, compresses responses and **load-balances** across instances. Learn server blocks, upstreams, and how proxy headers like `X-Forwarded-For` reach your app.$s$, ARRAY[$s$Reverse proxies face clients; apps stay private$s$,$s$Terminate TLS at the proxy$s$,$s$Round-robin and least-connections balancing$s$,$s$Forward client IP with X-Forwarded-For$s$]::text[], ARRAY[]::text[], 15, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-excel$s$, $s$excel$s$, $s$Excel & Spreadsheets$s$, $s$Spreadsheets are the analyst's first tool. Learn **relative vs absolute references** (`$A$1`), lookups (`XLOOKUP`/`VLOOKUP`), conditional aggregates (`SUMIFS`, `COUNTIFS`) and **pivot tables** for fast summaries. Keep raw data, calculations and outputs on separate sheets.$s$, ARRAY[$s$$ locks a row or column reference$s$,$s$XLOOKUP replaces VLOOKUP and INDEX/MATCH$s$,$s$Pivot tables summarise without formulas$s$,$s$Separate raw data from analysis$s$]::text[], ARRAY[]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-statistics$s$, $s$statistics$s$, $s$Statistics Fundamentals$s$, $s$Statistics separates signal from noise. Describe data with **mean, median and spread**; reason about samples with the **central limit theorem**; test hypotheses with **p-values** and report **confidence intervals**. Correlation does not imply causation, and the median resists outliers.$s$, ARRAY[$s$Median is robust to outliers; mean is not$s$,$s$A p-value is P(data this extreme | null is true)$s$,$s$Confidence intervals show the plausible range$s$,$s$Correlation is not causation$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-data-cleaning$s$, $s$data-cleaning$s$, $s$Data Cleaning & Wrangling$s$, $s$Real data is messy, and cleaning is most of an analyst's job. Profile first (row counts, nulls, distinct values), then fix **types**, standardise **formats**, remove **duplicates**, and decide explicitly how to treat **missing values** and outliers. Document every rule so results are reproducible.$s$, ARRAY[$s$Profile before you clean$s$,$s$Decide on missing values: drop, impute or flag$s$,$s$Deduplicate on a clear key$s$,$s$Keep cleaning steps scripted and reproducible$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-numpy$s$, $s$numpy$s$, $s$NumPy$s$, $s$NumPy's **ndarray** stores numbers in contiguous memory so operations run in fast C loops. Replace Python loops with **vectorised** expressions, understand **broadcasting** rules for combining shapes, and use boolean masks for filtering.$s$, ARRAY[$s$Vectorise instead of looping$s$,$s$Broadcasting aligns shapes from the right$s$,$s$Boolean masks filter arrays$s$,$s$Check .shape and .dtype constantly$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-pandas$s$, $s$pandas$s$, $s$pandas for Data Analysis$s$, $s$pandas brings SQL-like operations to Python. A **DataFrame** is a table of typed columns. Filter with boolean masks, `groupby().agg()` to summarise, `merge` to join, and `pivot_table` to reshape. Avoid row-by-row `apply` when a vectorised method exists.$s$, ARRAY[$s$groupby + agg = SQL GROUP BY$s$,$s$merge = SQL JOIN$s$,$s$Use .loc for label-based selection$s$,$s$Vectorised ops beat apply$s$]::text[], ARRAY[]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-data-visualization$s$, $s$data-visualization$s$, $s$Data Visualization$s$, $s$Pick the chart for the question: **bar** to compare categories, **line** for change over time, **scatter** for relationships, **histogram** for distributions. Start bar axes at zero, remove chart junk, label directly, and use colour to highlight, not decorate.$s$, ARRAY[$s$Bar = compare, line = trend, scatter = relationship$s$,$s$Bar charts start at zero$s$,$s$Highlight the one thing that matters$s$,$s$Avoid pie charts with many slices$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-bi-tools$s$, $s$bi-tools$s$, $s$BI Tools (Tableau, Power BI)$s$, $s$BI tools connect to data sources and let you build **interactive dashboards**. Model data cleanly first (one fact table, dimension tables), define **measures** once (DAX in Power BI, calculated fields in Tableau), and design dashboards around the decisions their users make.$s$, ARRAY[$s$Clean model first, visuals second$s$,$s$Define metrics once and reuse them$s$,$s$Filters and drill-downs replace many static charts$s$,$s$Every dashboard answers a named question$s$]::text[], ARRAY[]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-analytics-engineering$s$, $s$analytics-engineering$s$, $s$Analytics Engineering (dbt)$s$, $s$**dbt** turns SQL `SELECT`s into versioned, tested models in the warehouse (Snowflake, BigQuery). Layer models from staging to marts, use a **star schema** (facts and dimensions) for reporting, and add tests for uniqueness and not-null keys.$s$, ARRAY[$s$Staging, intermediate, marts$s$,$s$Facts hold events, dimensions describe them$s$,$s$Test keys for unique and not_null$s$,$s$Docs and lineage come from the code$s$]::text[], ARRAY[]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-data-storytelling$s$, $s$data-storytelling$s$, $s$Data Storytelling$s$, $s$Analysis only matters if it changes a decision. Lead with the **answer and recommendation**, support it with two or three charts, quantify impact, and state caveats plainly. Tailor depth to the audience: executives want the "so what", analysts want the method.$s$, ARRAY[$s$Answer first, then evidence$s$,$s$One message per chart$s$,$s$Quantify the impact of the recommendation$s$,$s$State assumptions and limitations$s$]::text[], ARRAY[]::text[], 15, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-ab-testing$s$, $s$ab-testing$s$, $s$A/B Testing & Experimentation$s$, $s$An A/B test randomly splits users to measure a change's causal effect. Define one **primary metric** and guardrails up front, compute the **sample size** from the minimum detectable effect, run for full weeks, and do not stop early when the result looks significant ("peeking").$s$, ARRAY[$s$Randomise at the unit you analyse$s$,$s$Pick the primary metric before launch$s$,$s$Sample size depends on baseline and minimum detectable effect$s$,$s$Peeking inflates false positives$s$]::text[], ARRAY[$s$posthog-docs$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-product-analytics$s$, $s$product-analytics$s$, $s$Product Analytics$s$, $s$Product analytics explains how users move through a product. **Funnels** show where users drop off, **cohorts** show whether retention improves over time, and a **North Star metric** captures the value users get. Instrument events with consistent names and properties.$s$, ARRAY[$s$Funnels locate drop-off$s$,$s$Cohort retention curves should flatten, not hit zero$s$,$s$North Star = delivered user value, with input metrics beneath it$s$,$s$Consistent event naming makes analysis possible$s$]::text[], ARRAY[$s$posthog-docs$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-math-for-ml$s$, $s$math-for-ml$s$, $s$Math for Machine Learning$s$, $s$ML models are functions of **vectors and matrices** trained by **gradient descent**: compute the derivative of the loss with respect to each parameter and step against it. Know matrix multiplication shapes, the dot product as similarity, and how the learning rate affects convergence.$s$, ARRAY[$s$(m x n) times (n x p) gives (m x p)$s$,$s$The gradient points uphill; step the other way$s$,$s$Too high a learning rate diverges, too low crawls$s$,$s$Dot product measures alignment of vectors$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-ml-fundamentals$s$, $s$ml-fundamentals$s$, $s$Machine Learning Fundamentals$s$, $s$Supervised learning fits a model from labelled examples. Split data into **train/validation/test**, start with a simple baseline, and watch for **overfitting** (great training score, poor validation). Choose metrics that match the problem: precision/recall for imbalanced classes, RMSE for regression. Never let test data leak into training.$s$, ARRAY[$s$Train, validate, then test once$s$,$s$Overfitting: low training error, high validation error$s$,$s$Accuracy misleads on imbalanced data$s$,$s$Data leakage makes results look better than reality$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-deep-learning$s$, $s$deep-learning$s$, $s$Deep Learning (PyTorch)$s$, $s$Neural networks stack layers of linear transforms and non-linear activations, trained by **backpropagation**. A PyTorch training loop is: forward pass, compute loss, `loss.backward()`, `optimizer.step()`, `optimizer.zero_grad()`. Use GPUs, mini-batches, and regularisation (dropout, weight decay) to train well.$s$, ARRAY[$s$Forward, loss, backward, step, zero_grad$s$,$s$Activations add non-linearity$s$,$s$Batch size and learning rate interact$s$,$s$Dropout and weight decay fight overfitting$s$]::text[], ARRAY[]::text[], 45, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-nlp-transformers$s$, $s$nlp-transformers$s$, $s$NLP & Transformers$s$, $s$Transformers process text as **tokens** mapped to **embeddings** and use **self-attention** to let every token weigh every other token. Encoder models (BERT) suit classification and embeddings; decoder models (GPT) generate text. Hugging Face provides pretrained models to fine-tune.$s$, ARRAY[$s$Text becomes tokens, tokens become vectors$s$,$s$Self-attention relates every token to every other$s$,$s$Encoders understand, decoders generate$s$,$s$Fine-tune pretrained models instead of training from scratch$s$]::text[], ARRAY[]::text[], 45, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-llm-applications$s$, $s$llm-applications$s$, $s$LLM Apps & Prompt Engineering$s$, $s$LLM features are built from **prompts, tools and evaluation**. Give clear instructions and examples, request **structured output** and validate it, let the model call **tools** for facts it cannot know, and build an **eval set** before tuning prompts. Never trust model output for URLs, numbers or security decisions without checking.$s$, ARRAY[$s$Validate structured output with a schema$s$,$s$Tools/function calling ground the model in real data$s$,$s$Build evals before iterating on prompts$s$,$s$Models hallucinate; verify facts and links$s$]::text[], ARRAY[]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-rag-vector-search$s$, $s$rag-vector-search$s$, $s$RAG & Vector Search$s$, $s$Retrieval-augmented generation answers questions from your own data: **chunk** documents, **embed** each chunk, store vectors in a **vector database**, retrieve the nearest chunks for a query (often combined with keyword search), and pass them to the model with instructions to cite them. Measure retrieval quality separately from answer quality.$s$, ARRAY[$s$Chunk size trades context for precision$s$,$s$Cosine similarity ranks nearest chunks$s$,$s$Hybrid search mixes keywords and vectors$s$,$s$Evaluate retrieval (recall@k) and answers separately$s$]::text[], ARRAY[]::text[], 36, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-mlops$s$, $s$mlops$s$, $s$MLOps & Model Deployment$s$, $s$MLOps applies DevOps to models. **Track experiments** (parameters, data versions, metrics), package models in containers, serve them behind an API, and **monitor** for data drift and performance decay. Reproducibility needs versioned data, code and environment.$s$, ARRAY[$s$Version data, code and model together$s$,$s$Track every experiment$s$,$s$Monitor input drift and prediction quality$s$,$s$Retrain on a schedule or on drift alerts$s$]::text[], ARRAY[]::text[], 45, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-data-pipelines$s$, $s$data-pipelines$s$, $s$Data Pipelines (Spark, Airflow)$s$, $s$Data pipelines move and transform data on a schedule. **Spark** distributes transformations across a cluster using lazy DataFrames; **Airflow** orchestrates tasks as DAGs with retries and backfills. Make tasks **idempotent** so reruns are safe, and partition data by date.$s$, ARRAY[$s$Spark is lazy until an action runs$s$,$s$Airflow DAGs define dependencies and schedules$s$,$s$Idempotent tasks make backfills safe$s$,$s$Partition by date for efficient reads$s$]::text[], ARRAY[]::text[], 45, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-computer-vision$s$, $s$computer-vision$s$, $s$Computer Vision$s$, $s$Computer vision models learn features from pixels. **CNNs** use convolutions to detect local patterns; vision transformers split images into patches. Tasks range from classification to **object detection** (boxes, e.g. YOLO) and **segmentation** (pixel masks). Augmentation and transfer learning matter more than architecture for small datasets.$s$, ARRAY[$s$Convolutions share weights across the image$s$,$s$Detection predicts boxes; segmentation predicts masks$s$,$s$Transfer learning beats training from scratch on small data$s$,$s$Augment data to improve robustness$s$]::text[], ARRAY[]::text[], 45, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-llm-fine-tuning$s$, $s$llm-fine-tuning$s$, $s$Fine-Tuning LLMs$s$, $s$Fine-tune only when prompting and retrieval are not enough. **LoRA** trains small low-rank adapter matrices instead of all weights; **QLoRA** does it on a quantised model to fit consumer GPUs. Quality depends mostly on clean, representative training data and a held-out evaluation set.$s$, ARRAY[$s$Try prompting and RAG first$s$,$s$LoRA trains small adapters, not all weights$s$,$s$QLoRA quantises the base model to save memory$s$,$s$Data quality beats data quantity$s$]::text[], ARRAY[]::text[], 45, FALSE, $s$draft$s$, TRUE, 1),
($s$lesson-product-discovery$s$, $s$product-discovery$s$, $s$User Research & Discovery$s$, $s$Discovery reduces the risk of building the wrong thing. Interview users about **past behaviour, not hypothetical futures** (The Mom Test), look for repeated pain, and synthesise findings into problems, **jobs to be done** and personas. Separate the problem from your favourite solution.$s$, ARRAY[$s$Ask about what people did, not what they would do$s$,$s$Compliments are not evidence$s$,$s$Synthesize patterns across 5+ interviews$s$,$s$Frame the problem before proposing solutions$s$]::text[], ARRAY[$s$gv-user-interviews$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-market-research$s$, $s$market-research$s$, $s$Market Sizing & Competitive Analysis$s$, $s$**TAM** is the whole market, **SAM** the part your product can serve, and **SOM** what you can realistically win. Size bottom-up (customers x price) rather than quoting top-down reports. Map competitors on the dimensions customers care about and identify what makes your position defensible.$s$, ARRAY[$s$TAM > SAM > SOM$s$,$s$Bottom-up sizing is more credible$s$,$s$Compare competitors on customer-valued dimensions$s$,$s$Moats: network effects, switching costs, data, brand$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-prd-writing$s$, $s$prd-writing$s$, $s$PRDs & User Stories$s$, $s$A PRD aligns the team on **why** and **what**, leaving **how** to engineering and design. Include the problem, target users, goals and success metrics, scope and non-goals, user stories ("As a..., I want..., so that...") with **acceptance criteria**, edge cases and open questions.$s$, ARRAY[$s$Problem and success metric come first$s$,$s$Non-goals prevent scope creep$s$,$s$Acceptance criteria are testable$s$,$s$List open questions and risks$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-prioritization$s$, $s$prioritization$s$, $s$Prioritization Frameworks$s$, $s$**RICE** scores ideas by Reach x Impact x Confidence / Effort. **MoSCoW** buckets scope into Must, Should, Could and Won't. Frameworks make trade-offs explicit and comparable, but they inform judgment rather than replace it; revisit scores as evidence changes.$s$, ARRAY[$s$RICE = Reach x Impact x Confidence / Effort$s$,$s$MoSCoW: Must, Should, Could, Won't$s$,$s$Confidence penalises guesses$s$,$s$Frameworks support judgment, they do not replace it$s$]::text[], ARRAY[]::text[], 15, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-agile-delivery$s$, $s$agile-delivery$s$, $s$Agile, Scrum & Delivery$s$, $s$Agile teams deliver in small increments and adjust from feedback. **Scrum** uses fixed sprints with planning, daily stand-ups, review and retrospective; **Kanban** limits work in progress on a continuous flow. Keep the backlog refined and stories small enough to finish in a few days.$s$, ARRAY[$s$Small batches give faster feedback$s$,$s$Scrum ceremonies: planning, daily, review, retro$s$,$s$Kanban limits work in progress$s$,$s$A story is done when it meets the definition of done$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-product-strategy$s$, $s$product-strategy$s$, $s$Product Strategy & Roadmapping$s$, $s$Strategy is a set of choices about **where to play and how to win**. Translate the vision into a few measurable goals (OKRs), then a **roadmap of outcomes**, not a list of features with dates. Communicate what you are not doing as clearly as what you are.$s$, ARRAY[$s$Strategy is choosing what not to do$s$,$s$Roadmaps should show outcomes and problems$s$,$s$OKRs: an objective plus measurable key results$s$,$s$Revisit strategy when evidence changes$s$]::text[], ARRAY[]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-stakeholder-management$s$, $s$stakeholder-management$s$, $s$Stakeholder Management$s$, $s$Influence without authority starts with understanding what each stakeholder needs. Map stakeholders by influence and interest, share context early, write decisions down with their rationale, and **disagree and commit** once a decision is made. Surprises erode trust faster than bad news.$s$, ARRAY[$s$Map stakeholders by influence and interest$s$,$s$Share bad news early$s$,$s$Write decisions and rationale down$s$,$s$Disagree, then commit$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-product-sense$s$, $s$product-sense$s$, $s$Product Sense$s$, $s$Product sense interviews test structured creativity. Clarify the goal, pick a **user segment**, list their **pain points**, prioritise one, brainstorm solutions, choose with explicit trade-offs, and define **success metrics** and risks. Show your reasoning out loud.$s$, ARRAY[$s$Goal, users, pains, solutions, metrics$s$,$s$Pick one segment and go deep$s$,$s$Prioritise pains by frequency and severity$s$,$s$End with metrics and risks$s$]::text[], ARRAY[$s$cracking-the-pm-interview$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-design-principles$s$, $s$design-principles$s$, $s$Visual Hierarchy & Design Principles$s$, $s$Good interfaces guide the eye. Build **hierarchy** with size, weight and colour so the most important element wins; group related items by **proximity**; **align** everything to a shared edge; and use generous **whitespace**. Consistency lets users predict how things work.$s$, ARRAY[$s$Hierarchy: one clear primary element per view$s$,$s$Proximity groups related items$s$,$s$Alignment creates order$s$,$s$Whitespace is a feature, not wasted space$s$]::text[], ARRAY[$s$material-design-3$s$]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-typography$s$, $s$typography$s$, $s$Typography$s$, $s$Most interfaces are text. Use a **type scale** (e.g. ratio 1.25) for consistent sizes, keep body text at 16px or more with line height around 1.5, limit line length to about 45-75 characters, and stick to one or two typefaces with clear weight contrast.$s$, ARRAY[$s$Use a modular type scale$s$,$s$Body text 16px+, line height ~1.5$s$,$s$45-75 characters per line$s$,$s$One or two typefaces are enough$s$]::text[], ARRAY[$s$material-design-3$s$]::text[], 15, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-color-theory$s$, $s$color-theory$s$, $s$Color & Contrast$s$, $s$Define colours by **role** (primary, surface, text, success, danger) rather than by hue, with a range of shades for each. Check **contrast** (4.5:1 for body text) and never use colour as the only signal; pair it with icons or text. Design light and dark themes from the same tokens.$s$, ARRAY[$s$Name colours by role, not hue$s$,$s$Body text contrast at least 4.5:1$s$,$s$Never rely on colour alone$s$,$s$Shades give depth without new hues$s$]::text[], ARRAY[$s$material-design-3$s$]::text[], 12, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-grid-systems$s$, $s$grid-systems$s$, $s$Layout Grids & Spacing$s$, $s$Grids make layouts consistent and responsive. Use a **column grid** (12 columns on desktop, 4 on mobile) with consistent gutters, and a **spacing scale** based on 8 (4, 8, 16, 24, 32...). When every gap comes from the scale, screens feel coherent.$s$, ARRAY[$s$12 columns desktop, 4 on mobile$s$,$s$Spacing from a scale of 4/8$s$,$s$Gutters stay consistent$s$,$s$Align content to columns, not arbitrary positions$s$]::text[], ARRAY[]::text[], 12, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-figma$s$, $s$figma$s$, $s$Figma Fundamentals$s$, $s$Figma is the industry-standard design tool. Work in **frames** (screens), organise **layers** with clear names, define reusable **styles** for colour and text, and collaborate through comments and shared libraries. Learn keyboard shortcuts early.$s$, ARRAY[$s$Frames are screens or containers$s$,$s$Name layers for handoff$s$,$s$Styles keep colour and type consistent$s$,$s$Comment and share instead of exporting$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-figma-auto-layout$s$, $s$figma-auto-layout$s$, $s$Figma Auto Layout & Components$s$, $s$**Auto Layout** makes frames behave like Flexbox: direction, spacing, padding and resizing (hug, fill, fixed). **Components** with **variants** and properties (boolean, text, instance swap) let one master drive every instance, so updates propagate everywhere.$s$, ARRAY[$s$Auto Layout = Flexbox for designers$s$,$s$Hug contents vs fill container$s$,$s$Variants model states like hover and disabled$s$,$s$Edit the main component, not instances$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-design-systems$s$, $s$design-systems$s$, $s$Design Systems & Tokens$s$, $s$A design system is the shared language between design and engineering: **tokens** (colour, type, spacing, radius), **components** with documented states, and usage guidelines. Name tokens by purpose (`color.text.muted`), version the system, and keep Figma and code in sync.$s$, ARRAY[$s$Tokens: the smallest named design decisions$s$,$s$Document states and usage for every component$s$,$s$Purpose-based names survive rebrands$s$,$s$Version and communicate changes$s$]::text[], ARRAY[$s$material-design-3$s$]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-wireframing$s$, $s$wireframing$s$, $s$Wireframing & User Flows$s$, $s$**User flows** map the steps a user takes to reach a goal; **wireframes** sketch the structure of each screen without visual polish. Staying low-fidelity keeps feedback focused on structure and makes throwing ideas away cheap.$s$, ARRAY[$s$Flow first, screens second$s$,$s$Low fidelity invites honest feedback$s$,$s$Include empty, error and loading states$s$,$s$Annotate intent for engineers$s$]::text[], ARRAY[]::text[], 15, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-prototyping$s$, $s$prototyping$s$, $s$Interactive Prototyping$s$, $s$Prototypes let you test an experience before anyone writes code. Link frames with interactions, use smart animate for transitions, and build only the paths you need to test. Match fidelity to the question: low for flow, high for visual and interaction details.$s$, ARRAY[$s$Prototype the path you are testing$s$,$s$Fidelity matches the question$s$,$s$Smart animate for transitions$s$,$s$Prototypes are disposable$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-interaction-design$s$, $s$interaction-design$s$, $s$Interaction Design$s$, $s$Interaction design shapes how a product responds. Every action needs **feedback** within about 100 ms, controls need clear **affordances**, and every component needs designed states (default, hover, focus, active, disabled, loading, error). Motion should explain change, not decorate; respect reduced-motion settings.$s$, ARRAY[$s$Feedback within ~100 ms feels instant$s$,$s$Design every state, including errors$s$,$s$Motion explains spatial change$s$,$s$Respect prefers-reduced-motion$s$]::text[], ARRAY[]::text[], 24, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-usability-testing$s$, $s$usability-testing$s$, $s$Usability Testing$s$, $s$Give 5 representative users realistic **tasks**, ask them to **think aloud**, and observe without helping. Note where they hesitate or fail, rate severity, and fix the worst issues first. A quick **heuristic evaluation** (e.g. Nielsen's 10) catches obvious problems before testing.$s$, ARRAY[$s$Five users find most major issues$s$,$s$Give tasks, not instructions$s$,$s$Do not lead or help$s$,$s$Prioritise by severity and frequency$s$]::text[], ARRAY[$s$gv-user-interviews$s$]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-information-architecture$s$, $s$information-architecture$s$, $s$Information Architecture$s$, $s$Information architecture decides how content is grouped, labelled and navigated. Use **card sorting** to learn users' mental models, a **sitemap** to define structure, and **tree testing** to check people can find things. Label in users' words, not internal jargon.$s$, ARRAY[$s$Card sorting reveals mental models$s$,$s$Tree testing validates navigation$s$,$s$Use users' vocabulary for labels$s$,$s$Shallow, clear hierarchies beat deep ones$s$]::text[], ARRAY[]::text[], 18, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-ux-writing$s$, $s$ux-writing$s$, $s$UX Writing & Microcopy$s$, $s$Words are interface. Write **buttons as verbs** that describe the outcome ("Save changes"), **errors** that say what happened and how to fix it, and **empty states** that suggest the next step. Be concise, consistent and human.$s$, ARRAY[$s$Buttons describe the action's result$s$,$s$Errors explain the problem and the fix$s$,$s$Empty states suggest a next step$s$,$s$Use the same word for the same thing everywhere$s$]::text[], ARRAY[]::text[], 12, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-design-portfolio$s$, $s$design-portfolio$s$, $s$Design Portfolio & Case Studies$s$, $s$Hiring managers skim. Show **2-3 deep case studies** rather than many shallow ones. Each should state the problem, your role, constraints, the process (research, iterations, trade-offs), the final design and the **measured outcome**. Show messy middle steps; they prove your thinking.$s$, ARRAY[$s$Quality over quantity: 2-3 case studies$s$,$s$State your role and constraints$s$,$s$Show iterations and trade-offs$s$,$s$End with outcomes and learnings$s$]::text[], ARRAY[]::text[], 30, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-oop$s$, $s$oop$s$, $s$Object-Oriented Programming$s$, $s$Object-oriented programming models a program as objects that hold data and behaviour. The four pillars are encapsulation (hide state behind methods), abstraction (expose what, not how), inheritance (reuse and specialise) and polymorphism (one interface, many implementations). Campus interviews ask you to define each with an example, compare abstract classes and interfaces, and design small systems such as a parking lot.$s$, ARRAY[$s$Explain each pillar with a short code example.$s$,$s$Prefer composition over inheritance when behaviour varies.$s$,$s$SOLID keeps classes small and easy to change.$s$]::text[], ARRAY[$s$refactoring-guru$s$]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-operating-systems$s$, $s$operating-systems$s$, $s$Operating Systems$s$, $s$An operating system shares the CPU, memory and devices between programs. Interviews focus on processes versus threads, scheduling algorithms, race conditions and locks, the four conditions for deadlock, and virtual memory with paging. Be ready to compute waiting times for a small scheduling example and to explain what happens on a page fault.$s$, ARRAY[$s$A process has its own address space; threads share one.$s$,$s$Deadlock needs mutual exclusion, hold and wait, no preemption and circular wait.$s$,$s$Paging maps virtual pages to physical frames.$s$]::text[], ARRAY[$s$ostep$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-computer-networks$s$, $s$computer-networks$s$, $s$Computer Networks$s$, $s$Computer networks move data in layers: application (HTTP, DNS), transport (TCP, UDP), network (IP) and link. Interviews ask what happens when you type a URL, how TCP makes delivery reliable, the difference between TCP and UDP, how DNS resolves a name, and how HTTPS protects traffic with TLS.$s$, ARRAY[$s$TCP is reliable and ordered; UDP is fast and connectionless.$s$,$s$DNS turns a name into an IP address through a chain of servers.$s$,$s$HTTPS is HTTP over TLS.$s$]::text[], ARRAY[$s$mdn-http-overview$s$,$s$cloudflare-learning$s$]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-dbms$s$, $s$dbms$s$, $s$Database Management Systems$s$, $s$A DBMS stores data safely and answers queries. Interviews cover keys (primary, foreign, candidate), normal forms up to BCNF, joins and aggregation in SQL, ACID transactions, isolation levels and their anomalies, and how B-tree indexes speed up lookups. Expect to write two or three SQL queries live.$s$, ARRAY[$s$Normalise to remove update anomalies; denormalise for read speed.$s$,$s$ACID: atomicity, consistency, isolation, durability.$s$,$s$An index trades write cost and space for faster reads.$s$]::text[], ARRAY[$s$sqlbolt$s$,$s$postgresql-tutorial$s$,$s$use-the-index-luke$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-aptitude-quant$s$, $s$aptitude-quant$s$, $s$Quantitative Aptitude$s$, $s$Quantitative aptitude sections in campus tests (TCS NQT, Infosys, Wipro, Accenture, Cognizant, Capgemini) reward speed with a small set of formulas. Learn the shortcut for each topic, practise under a timer, and skip a question that takes more than two minutes.$s$, ARRAY[$s$Convert percentages to fractions (12.5% = 1/8) to calculate faster.$s$,$s$Time and work: add rates, not times.$s$,$s$Check the answer options before solving fully.$s$]::text[], ARRAY[$s$khan-academy-math$s$,$s$indiabix-aptitude$s$]::text[], 45, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-aptitude-logical$s$, $s$aptitude-logical$s$, $s$Logical Reasoning$s$, $s$Logical reasoning tests pattern spotting and careful reading. Draw diagrams for blood relations, directions and seating; write the rules of a code before decoding; and for syllogisms use Venn diagrams rather than intuition.$s$, ARRAY[$s$Draw, do not imagine: a quick diagram prevents most errors.$s$,$s$Number series: check differences, then ratios, then alternating patterns.$s$,$s$Syllogisms: a conclusion must hold in every possible diagram.$s$]::text[], ARRAY[$s$indiabix-logical$s$]::text[], 36, TRUE, $s$draft$s$, TRUE, 1),
($s$lesson-aptitude-verbal$s$, $s$aptitude-verbal$s$, $s$Verbal Ability$s$, $s$Verbal sections check reading speed and grammar. Read the questions before the passage, answer from the text rather than opinion, and learn the common error types: subject-verb agreement, tense, articles, prepositions and parallel structure.$s$, ARRAY[$s$Answer from the passage, not from what you already know.$s$,$s$Para-jumbles: find the opening sentence and linked pairs first.$s$,$s$Most correction questions test agreement, tense or prepositions.$s$]::text[], ARRAY[$s$indiabix-verbal$s$]::text[], 30, TRUE, $s$draft$s$, TRUE, 1)
