($s$dev.backend-core.rest-api-design-collections.q1$s$, $s$rest-api-design$s$, $s$lesson-rest-api-design$s$, $s$mcq$s$, $s$easy$s$, ARRAY[]::text[], $s${"id":"dev.backend-core.rest-api-design-collections.q1","skill_id":"rest-api-design","lesson_id":"lesson-rest-api-design","prompt":"Why is cursor pagination preferred for a feed where new items keep arriving?","explanation":"Offsets shift when rows are added; a cursor anchors on the last item returned, so pages stay consistent.","difficulty":"easy","company_tags":[],"status":"draft","ai_drafted":true,"version":1,"kind":"mcq","options":["It allows jumping to page 500 directly","It needs no index","It is the only kind browsers support","It continues from the last seen item, so inserts do not cause skips or repeats"],"correct":[3]}$s$::jsonb, $s$draft$s$, TRUE, 1),
