($s$dev.backend-scale.message-queues.q2$s$, $s$message-queues$s$, $s$lesson-message-queues$s$, $s$mcq$s$, $s$easy$s$, ARRAY[]::text[], $s${"id":"dev.backend-scale.message-queues.q2","skill_id":"message-queues","lesson_id":"lesson-message-queues","prompt":"In RabbitMQ, which exchange type copies every message to all bound queues regardless of routing key?","explanation":"A fanout exchange ignores the routing key and broadcasts to every queue bound to it.","difficulty":"easy","company_tags":[],"status":"draft","ai_drafted":true,"version":1,"kind":"mcq","options":["Direct","Topic","Fanout","Default"],"correct":[2]}$s$::jsonb, $s$draft$s$, TRUE, 1),
($s$dev.backend-scale.message-queues-kafka.q1$s$, $s$message-queues$s$, $s$lesson-message-queues$s$, $s$mcq$s$, $s$easy$s$, ARRAY[]::text[], $s${"id":"dev.backend-scale.message-queues-kafka.q1","skill_id":"message-queues","lesson_id":"lesson-message-queues","prompt":"A topic has 4 partitions and a consumer group has 6 consumers. What happens?","explanation":"Within a group a partition is assigned to one consumer only, so consumers beyond the partition count sit idle.","difficulty":"easy","company_tags":[],"status":"draft","ai_drafted":true,"version":1,"kind":"mcq","options":["Each consumer reads a third of every partition","Kafka creates 2 extra partitions automatically","All 6 consumers read every message","4 consumers each get a partition and 2 stay idle"],"correct":[3]}$s$::jsonb, $s$draft$s$, TRUE, 1),
