($s$dev.backend-scale.fullstack-architecture.q1$s$, $s$fullstack-architecture$s$, $s$lesson-fullstack-architecture$s$, $s$mcq$s$, $s$easy$s$, ARRAY[]::text[], $s${"id":"dev.backend-scale.fullstack-architecture.q1","skill_id":"fullstack-architecture","lesson_id":"lesson-fullstack-architecture","prompt":"Why must the server validate input even when the client already validates it?","explanation":"Anyone can call the API with curl or a script, so the server is the only place validation is guaranteed.","difficulty":"easy","company_tags":[],"status":"draft","ai_drafted":true,"version":1,"kind":"mcq","options":["Client validation is slower than server validation","Requests can be sent directly to the API, bypassing the client","Browsers ignore client-side validation","Validation libraries only work on the server"],"correct":[1]}$s$::jsonb, $s$draft$s$, TRUE, 1),
($s$dev.backend-scale.fullstack-architecture.q2$s$, $s$fullstack-architecture$s$, $s$lesson-fullstack-architecture$s$, $s$mcq$s$, $s$easy$s$, ARRAY[]::text[], $s${"id":"dev.backend-scale.fullstack-architecture.q2","skill_id":"fullstack-architecture","lesson_id":"lesson-fullstack-architecture","prompt":"Where should the rule \"a coupon can be used once per user\" be enforced?","explanation":"Business rules must run on the server, where the user cannot skip or change them.","difficulty":"easy","company_tags":[],"status":"draft","ai_drafted":true,"version":1,"kind":"mcq","options":["In the React component","In local storage","In the server-side service layer","In the CSS of the checkout page"],"correct":[2]}$s$::jsonb, $s$draft$s$, TRUE, 1),
