($s$dev.backend-scale.fullstack-architecture-data.q2$s$, $s$fullstack-architecture$s$, $s$lesson-fullstack-architecture$s$, $s$mcq$s$, $s$easy$s$, ARRAY[]::text[], $s${"id":"dev.backend-scale.fullstack-architecture-data.q2","skill_id":"fullstack-architecture","lesson_id":"lesson-fullstack-architecture","prompt":"Why does cursor pagination usually beat OFFSET 100000 LIMIT 20 on a large table?","explanation":"A large OFFSET scans and discards rows; WHERE id < cursor uses the index to jump straight to the page.","difficulty":"easy","company_tags":[],"status":"draft","ai_drafted":true,"version":1,"kind":"mcq","options":["Cursors compress the response","OFFSET is not supported by PostgreSQL","Cursors cache results in the browser","The database must still read and skip all offset rows, while a cursor seeks by index"],"correct":[3]}$s$::jsonb, $s$draft$s$, TRUE, 1),
